public class Product {
    private String name;
    private double price;
    private String productId;
    private int stockQuantity;
    private java.util.List<String> customerReviews;
    private double averageRating;
    private int totalSales;
    private double costPrice;

    private InventoryDatabase database;
    private NotificationService notificationService;

    public Product(String name, double price) {
        this.name = name;
        this.price = price;
        this.productId = "PRD-" + System.currentTimeMillis() % 100000;
        this.customerReviews = new java.util.ArrayList<>();
        this.averageRating = 0.0;
        this.totalSales = 0;
        this.stockQuantity = 100;
        this.costPrice = price * 0.6;
        this.database = new InventoryDatabase("jdbc:mysql://localhost:3306/inventory");
        this.notificationService = new NotificationService("API_KEY_12345");
    }

    public double applyDiscount(double percentage) {
        return price * (1 - percentage / 100);
    }

    public void displayProduct() {
        System.out.println("Product: " + name + ", Price: $" + price);
    }

    public double calculateDiscountedPrice(double discountPercentage) {
        double discounted = price * (1 - discountPercentage / 100);
        database.logTransaction("DISCOUNT_APPLIED", "Product: " + productId + ", Discount: " + discountPercentage + "%");
        return discounted;
    }

    public double calculateProfitMargin() {
        return ((price - costPrice) / price) * 100;
    }

    public double calculateShippingCost(String destination) {
        return destination.equalsIgnoreCase("international") ? 15.99 : 5.99;
    }

    public void addCustomerReview(String review, double rating) {
        if (rating >= 1.0 && rating <= 5.0) {
            customerReviews.add(review);
            averageRating = customerReviews.size() == 1 ? rating : (averageRating * (customerReviews.size() - 1) + rating) / customerReviews.size();
            database.logTransaction("REVIEW_ADDED", "Product: " + productId + ", Rating: " + rating);
        }
    }

    public void processSale(int quantity, String customerEmail) {
        if (stockQuantity >= quantity) {
            stockQuantity -= quantity;
            totalSales += quantity;
            database.updateStock(productId, stockQuantity);
            notificationService.sendEmail(customerEmail, "Purchase Confirmation", "Receipt for " + name);
            if (stockQuantity <= 10) {
                notificationService.sendEmail("inventory@company.com", "Low Stock Alert", "Product " + name + " low stock");
            }
            database.logTransaction("SALE_COMPLETED", "Product: " + productId + ", Quantity: " + quantity);
        }
    }

    public void restockProduct(int quantity, String supplierEmail) {
        stockQuantity += quantity;
        database.updateStock(productId, stockQuantity);
        notificationService.sendEmail(supplierEmail, "Restock Confirmation", "Added " + quantity + " units");
        database.logTransaction("RESTOCK_COMPLETED", "Product: " + productId + ", Added: " + quantity);
    }

    public String generateProductReport() {
        return "Product: " + name + "\nID: " + productId + "\nPrice: $" + price + "\nStock: " + stockQuantity + "\nSales: " + totalSales + "\nRating: " + averageRating;
    }

    public void displayDetailedProduct() {
        System.out.println(name + " (" + productId + ") - $" + price + " - Stock: " + stockQuantity + " - Rating: " + averageRating);
    }

    public String getName() {
        return name;
    }

    public double getPrice() {
        return price;
    }

    public void setPrice(double price) {
        this.price = price;
    }
}

