class Product:
    def __init__(self, name, price):
        self.name = name
        self.price = price
        self.product_id = f"PRD-{int(time.time() * 1000) % 100000}"
        self.customer_reviews = []
        self.average_rating = 0.0
        self.total_sales = 0
        self.stock_quantity = 100
        self.cost_price = price * 0.6
        self.database = InventoryDatabase("jdbc:mysql://localhost:3306/inventory")
        self.notification_service = NotificationService("API_KEY_12345")

    def apply_discount(self, percentage):
        return self.price * (1 - percentage / 100)

    def display_product(self):
        print(f"Product: {self.name}, Price: ${self.price}")

    def calculate_discounted_price(self, discount_percentage):
        discounted = self.price * (1 - discount_percentage / 100)
        self.database.log_transaction("DISCOUNT_APPLIED", f"Product: {self.product_id}, Discount: {discount_percentage}%")
        return discounted

    def calculate_profit_margin(self):
        return ((self.price - self.cost_price) / self.price) * 100

    def calculate_shipping_cost(self, destination):
        return 15.99 if destination.lower() == "international" else 5.99

    def add_customer_review(self, review, rating):
        if 1.0 <= rating <= 5.0:
            self.customer_reviews.append(review)
            if len(self.customer_reviews) == 1:
                self.average_rating = rating
            else:
                self.average_rating = (self.average_rating * (len(self.customer_reviews) - 1) + rating) / len(self.customer_reviews)
            self.database.log_transaction("REVIEW_ADDED", f"Product: {self.product_id}, Rating: {rating}")

    def process_sale(self, quantity, customer_email):
        if self.stock_quantity >= quantity:
            self.stock_quantity -= quantity
            self.total_sales += quantity
            self.database.update_stock(self.product_id, self.stock_quantity)
            self.notification_service.send_email(customer_email, "Purchase Confirmation", f"Receipt for {self.name}")
            if self.stock_quantity <= 10:
                self.notification_service.send_email("inventory@company.com", "Low Stock Alert", f"Product {self.name} low stock")
            self.database.log_transaction("SALE_COMPLETED", f"Product: {self.product_id}, Quantity: {quantity}")

    def restock_product(self, quantity, supplier_email):
        self.stock_quantity += quantity
        self.database.update_stock(self.product_id, self.stock_quantity)
        self.notification_service.send_email(supplier_email, "Restock Confirmation", f"Added {quantity} units")
        self.database.log_transaction("RESTOCK_COMPLETED", f"Product: {self.product_id}, Added: {quantity}")

    def generate_product_report(self):
        return f"Product: {self.name}\nID: {self.product_id}\nPrice: ${self.price}\nStock: {self.stock_quantity}\nSales: {self.total_sales}\nRating: {self.average_rating}"

    def display_detailed_product(self):
        print(f"{self.name} ({self.product_id}) - ${self.price} - Stock: {self.stock_quantity} - Rating: {self.average_rating}")

    def get_name(self):
        return self.name

    def get_price(self):
        return self.price

    def set_price(self, price):
        self.price = price

