public static class SecurityConfig
{
    public const int MaxLoginAttempts = 5;
    public const int PasswordExpiryDays = 90;
}

public class User
{
    public string Name { get; set; }
    public string Email { get; set; }
    public string Password { get; private set; }
    public bool IsActive { get; set; }
    public string Role { get; set; }
    public DateTime? LastLogin { get; set; }
    public int LoginAttempts { get; set; }
    public string PhoneNumber { get; set; }
    public DateTime RegistrationDate { get; set; }
    public List<string> LoginHistory { get; private set; }
    public Dictionary<string, string> Preferences { get; private set; }
    public List<string> Notifications { get; private set; }
    public string ProfilePictureUrl { get; set; }
    public bool EmailVerified { get; set; }

    private readonly DatabaseService _dbService;
    private readonly EmailService _emailService;
    private readonly SMSService _smsService;
    private readonly FileService _fileService;

    public User(string name, string email)
    {
        Name = name;
        Email = email;
        IsActive = true;
        Role = "USER";
        LoginAttempts = 0;
        RegistrationDate = DateTime.Now;
        LoginHistory = new List<string>();
        Preferences = new Dictionary<string, string>();
        Notifications = new List<string>();
        EmailVerified = false;

        _dbService = new DatabaseService("Server=localhost;Database=userdb;");
        _emailService = new EmailService("smtp.company.com", 587);
        _smsService = new SMSService("api_key_12345");
        _fileService = new FileService("/uploads");

        InitializeDefaultPreferences();
    }

    public void SaveToDatabase()
    {
        _dbService.SaveUser(this);
    }

    public void SendWelcomeEmail()
    {
        string subject = "Welcome to our platform!";
        string body = CreateWelcomeEmailBody();
        _emailService.SendEmail(Email, subject, body);
    }

    public void SendPasswordResetEmail()
    {
        string resetToken = GeneratePasswordResetToken();
        string subject = "Password Reset Request";
        string body = CreatePasswordResetEmailBody(resetToken);
        _emailService.SendEmail(Email, subject, body);
    }

    public void SendSMSVerification()
    {
        if (!string.IsNullOrEmpty(PhoneNumber))
        {
            string smsCode = GenerateSMSVerificationCode();
            string message = $"Your verification code: {smsCode}";
            _smsService.SendSMS(PhoneNumber, message);
        }
    }

    public string CreateWelcomeEmailBody()
    {
        return $"Dear {Name},\n\nWelcome to our platform! Complete your profile and explore our features.\n\nBest regards,\nThe Team";
    }

    public string CreatePasswordResetEmailBody(string token)
    {
        return $"Hello {Name},\n\nReset your password: https://oursite.com/reset?token={token}\n\nLink expires in 24 hours.";
    }

    public string GeneratePasswordResetToken()
    {
        long timestamp = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        string randomPart = new Random().NextDouble().ToString()[2..8];
        return $"RESET_{timestamp}_{randomPart}";
    }

    public string GenerateSMSVerificationCode()
    {
        return new Random().Next(100000, 1000000).ToString();
    }

    public bool ValidateEmailFormat(string email)
    {
        if (string.IsNullOrWhiteSpace(email))
            return false;
        return email.Contains("@") && email.Contains(".") && email.Split('@').Length == 2;
    }

    public bool ValidatePasswordStrength(string password)
    {
        if (string.IsNullOrEmpty(password) || password.Length < 8)
            return false;

        bool hasUpper = password.Any(char.IsUpper);
        bool hasLower = password.Any(char.IsLower);
        bool hasDigit = password.Any(char.IsDigit);
        bool hasSpecial = password.Any(c => "!@#$%^&*()_+-=[]{}|;:,.<>?".Contains(c));

        return hasUpper && hasLower && hasDigit && hasSpecial;
    }

    public string HashPassword(string password)
    {
        int hash = 7;
        foreach (char c in password)
        {
            hash = hash * 31 + c;
        }
        return $"HASH:{Math.Abs(hash):X}";
    }

    public bool VerifyPassword(string plainPassword, string hashedPassword)
    {
        string computedHash = HashPassword(plainPassword);
        return computedHash.Equals(hashedPassword);
    }

    public bool Authenticate(string password)
    {
        if (LoginAttempts >= SecurityConfig.MaxLoginAttempts)
        {
            Console.WriteLine("Account locked due to too many failed attempts");
            return false;
        }

        if (Password != null && VerifyPassword(password, Password))
        {
            LoginAttempts = 0;
            LastLogin = DateTime.Now;
            AddToLoginHistory("Successful login from IP: 192.168.1.100");
            return true;
        }

        LoginAttempts++;
        AddToLoginHistory("Failed login attempt from IP: 192.168.1.100");
        return false;
    }

    public void LockAccount()
    {
        IsActive = false;
        LogSecurityEvent("ACCOUNT_LOCKED", $"Account locked for user: {Name}");
        SendAccountNotification("Your account has been locked due to security reasons.");
    }

    public void UnlockAccount()
    {
        IsActive = true;
        LoginAttempts = 0;
        LogSecurityEvent("ACCOUNT_UNLOCKED", $"Account unlocked for user: {Name}");
        SendAccountNotification("Your account has been successfully unlocked.");
    }

    public void LogSecurityEvent(string eventType, string description)
    {
        DateTime timestamp = DateTime.Now;
        string logEntry = $"[{timestamp}] {eventType}: {description}";
        Console.WriteLine($"SECURITY LOG: {logEntry}");
    }

    public void SendAccountNotification(string message)
    {
        AddNotification(message);
        if (EmailVerified)
        {
            _emailService.SendEmail(Email, "Account Security Alert", message);
        }
        if (!string.IsNullOrEmpty(PhoneNumber))
        {
            _smsService.SendSMS(PhoneNumber, $"Security Alert: {message}");
        }
    }

    public void AddToLoginHistory(string entry)
    {
        string timestampedEntry = $"{DateTime.Now}: {entry}";
        LoginHistory.Add(timestampedEntry);
        if (LoginHistory.Count > 100)
        {
            LoginHistory.RemoveAt(0);
        }
    }

    private void InitializeDefaultPreferences()
    {
        Preferences["theme"] = "light";
        Preferences["language"] = "en";
        Preferences["notifications"] = "enabled";
    }

    public void UpdatePreference(string key, string value)
    {
        string oldValue = Preferences.ContainsKey(key) ? Preferences[key] : null;
        Preferences[key] = value;
        LogPreferenceChange(key, oldValue, value);
    }

    public void LogPreferenceChange(string key, string oldValue, string newValue)
    {
        string logEntry = $"Preference '{key}' changed from '{oldValue}' to '{newValue}'";
        Console.WriteLine($"PREFERENCE LOG: {logEntry}");
    }

    public string GetPreference(string key)
    {
        return Preferences.ContainsKey(key) ? Preferences[key] : null;
    }

    public void UploadProfilePicture(byte[] imageData, string fileName)
    {
        if (ValidateImageFile(imageData, fileName))
        {
            ProfilePictureUrl = _fileService.UploadFile(imageData, $"profile_{Name}_{fileName}");
            LogActivityEvent("PROFILE_PICTURE_UPLOADED", "User uploaded new profile picture");
        }
        else
        {
            throw new ArgumentException("Invalid image file");
        }
    }

    public bool ValidateImageFile(byte[] imageData, string fileName)
    {
        if (imageData == null || imageData.Length == 0 || imageData.Length > 5 * 1024 * 1024)
        {
            return false;
        }
        string lower = fileName.ToLower();
        return lower.EndsWith(".jpg") || lower.EndsWith(".jpeg") || 
               lower.EndsWith(".png") || lower.EndsWith(".gif");
    }

    public void LogActivityEvent(string eventType, string description)
    {
        DateTime timestamp = DateTime.Now;
        string logEntry = $"[{timestamp}] {eventType}: {description} (User: {Name})";
        Console.WriteLine($"ACTIVITY LOG: {logEntry}");
    }

    public void AddNotification(string message)
    {
        string timestampedNotification = $"{DateTime.Now}: {message}";
        Notifications.Add(timestampedNotification);
        if (Notifications.Count > 50)
        {
            Notifications.RemoveAt(0);
        }
    }

    public void ChangePassword(string oldPassword, string newPassword)
    {
        if (!Authenticate(oldPassword))
        {
            throw new UnauthorizedAccessException("Current password is incorrect");
        }

        if (!ValidatePasswordStrength(newPassword))
        {
            throw new ArgumentException("New password does not meet strength requirements");
        }

        Password = HashPassword(newPassword);
        LogSecurityEvent("PASSWORD_CHANGED", "Password changed successfully");
        SendAccountNotification("Your password has been changed successfully.");
    }

    public string GenerateUserReport()
    {
        var report = new StringBuilder();
        report.AppendLine("=== USER REPORT ===");
        report.AppendLine($"Name: {Name}");
        report.AppendLine($"Email: {Email}");
        report.AppendLine($"Active: {IsActive}");
        report.AppendLine($"Registration Date: {RegistrationDate}");
        report.AppendLine($"Login History: {LoginHistory.Count} entries");
        return report.ToString();
    }

    public void DeleteAccount()
    {
        LogSecurityEvent("ACCOUNT_DELETION_STARTED", "User initiated account deletion");
        IsActive = false;
        Email = "[DELETED]";
        Password = null;
        LoginHistory.Clear();
        Notifications.Clear();
        _dbService.DeleteUser(Name);
        LogSecurityEvent("ACCOUNT_DELETED", "Account deletion completed");
    }

    public void SetPassword(string password)
    {
        Password = HashPassword(password);
    }
}

