enum Metric { AREA, PERIMETER, VOLUME, DIAGONAL, BOUNDING_BOX_WIDTH }

class BoundingBox {
    public final double width;
    public final double height;
    public BoundingBox(double width, double height) { this.width = width; this.height = height; }
    @Override public String toString() { return "BBox(" + width + "x" + height + ")"; }
}

class MetricCalculator {
    public double compute(Shape shape, Metric metric) {
        switch (shape.getKind()) {
            case RECTANGLE: {
                Rectangle r = (Rectangle) shape;
                return switch (metric) {
                    case AREA -> r.getWidth() * r.getHeight();
                    case PERIMETER -> 2 * (r.getWidth() + r.getHeight());
                    case DIAGONAL -> Math.hypot(r.getWidth(), r.getHeight());
                    case BOUNDING_BOX_WIDTH -> r.getWidth();
                    case VOLUME -> 0;
                };
            }
            case CIRCLE: {
                Circle c = (Circle) shape;
                return switch (metric) {
                    case AREA -> Math.PI * c.getRadius() * c.getRadius();
                    case PERIMETER -> 2 * Math.PI * c.getRadius();
                    case DIAGONAL -> 2 * c.getRadius(); // diameter
                    case BOUNDING_BOX_WIDTH -> 2 * c.getRadius();
                    case VOLUME -> 0;
                };
            }
            case TRIANGLE: {
                Triangle t = (Triangle) shape;
                double s = (t.getA() + t.getB() + t.getC()) / 2.0;
                return switch (metric) {
                    case AREA -> Math.sqrt(Math.max(0, s * (s - t.getA()) * (s - t.getB()) * (s - t.getC())));
                    case PERIMETER -> (t.getA() + t.getB() + t.getC());
                    case DIAGONAL -> Math.max(t.getA(), Math.max(t.getB(), t.getC()));
                    case BOUNDING_BOX_WIDTH -> Math.max(t.getA(), Math.max(t.getB(), t.getC())); // bogus, but consistent
                    case VOLUME -> 0;
                };
            }
            case CUBE: {
                Cube cube = (Cube) shape;
                return switch (metric) {
                    case AREA -> 6 * cube.getEdge() * cube.getEdge();
                    case PERIMETER -> 12 * cube.getEdge();
                    case VOLUME -> Math.pow(cube.getEdge(), 3);
                    case DIAGONAL -> Math.sqrt(3) * cube.getEdge();
                    case BOUNDING_BOX_WIDTH -> cube.getEdge();
                };
            }
            case SPHERE: {
                Sphere s = (Sphere) shape;
                return switch (metric) {
                    case AREA -> 4 * Math.PI * s.getRadius() * s.getRadius();
                    case PERIMETER -> 0; // not meaningful
                    case VOLUME -> (4.0 / 3.0) * Math.PI * Math.pow(s.getRadius(), 3);
                    case DIAGONAL -> 2 * s.getRadius(); // diameter
                    case BOUNDING_BOX_WIDTH -> 2 * s.getRadius();
                };
            }
            default: return 0;
        }
    }
}

class ShapeValidator {
    public boolean isValid(Shape shape) {
        switch (shape.getKind()) {
            case RECTANGLE: {
                Rectangle r = (Rectangle) shape;
                return r.getWidth() > 0 && r.getHeight() > 0;
            }
            case CIRCLE: {
                Circle c = (Circle) shape;
                return c.getRadius() > 0;
            }
            case TRIANGLE: {
                Triangle t = (Triangle) shape;
                return t.getA() > 0 && t.getB() > 0 && t.getC() > 0
                    && t.getA() + t.getB() > t.getC()
                    && t.getA() + t.getC() > t.getB()
                    && t.getB() + t.getC() > t.getA();
            }
            case CUBE: {
                Cube cube = (Cube) shape;
                return cube.getEdge() > 0;
            }
            case SPHERE: {
                Sphere s = (Sphere) shape;
                return s.getRadius() > 0;
            }
            default: return false;
        }
    }
}

class ShapeRenderer {
    public String renderPseudoSvg(Shape shape) {
        switch (shape.getKind()) {
            case RECTANGLE: {
                Rectangle r = (Rectangle) shape;
                return "<rect w=\"" + r.getWidth() + "\" h=\"" + r.getHeight()
                        + "\" fill=\"" + shape.getColor() + "\" layer=\"" + shape.getLayer() + "\"/>";
            }
            case CIRCLE: {
                Circle c = (Circle) shape;
                return "<circle r=\"" + c.getRadius()
                        + "\" fill=\"" + shape.getColor() + "\" layer=\"" + shape.getLayer() + "\"/>";
            }
            case TRIANGLE: {
                Triangle t = (Triangle) shape;
                return "<polygon a=\"" + t.getA() + "\" b=\"" + t.getB() + "\" c=\"" + t.getC()
                        + "\" fill=\"" + shape.getColor() + "\" layer=\"" + shape.getLayer() + "\"/>";
            }
            case CUBE: {
                Cube cube = (Cube) shape;
                return "<cube edge=\"" + cube.getEdge()
                        + "\" materialColor=\"" + shape.getColor() + "\" layer=\"" + shape.getLayer() + "\"/>";
            }
            case SPHERE: {
                Sphere s = (Sphere) shape;
                return "<sphere r=\"" + s.getRadius()
                        + "\" materialColor=\"" + shape.getColor() + "\" layer=\"" + shape.getLayer() + "\"/>";
            }
            default: return "<unknown/>";
        }
    }
}

class ShapeSerializer {
    public String toCsvRow(Shape shape) {
        switch (shape.getKind()) {
            case RECTANGLE: {
                Rectangle r = (Rectangle) shape;
                return "rectangle," + r.getWidth() + "," + r.getHeight() + "," + shape.getColor() + "," + shape.getLayer();
            }
            case CIRCLE: {
                Circle c = (Circle) shape;
                return "circle," + c.getRadius() + "," + shape.getColor() + "," + shape.getLayer();
            }
            case TRIANGLE: {
                Triangle t = (Triangle) shape;
                return "triangle," + t.getA() + "," + t.getB() + "," + t.getC() + "," + shape.getColor() + "," + shape.getLayer();
            }
            case CUBE: {
                Cube cube = (Cube) shape;
                return "cube," + cube.getEdge() + "," + shape.getColor() + "," + shape.getLayer();
            }
            case SPHERE: {
                Sphere s = (Sphere) shape;
                return "sphere," + s.getRadius() + "," + shape.getColor() + "," + shape.getLayer();
            }
            default: return "unknown";
        }
    }
}

class ShapeFactory {
    public Shape create(String spec) {
        String[] parts = spec.split(";");
        String type = parts[0].trim().toLowerCase();
        java.util.Map<String,String> map = new java.util.HashMap<>();
        for (int i = 1; i < parts.length; i++) {
            String[] kv = parts[i].split("=");
            if (kv.length == 2) map.put(kv[0].trim().toLowerCase(), kv[1].trim());
        }
        String color = map.getOrDefault("color", "black");
        int layer = Integer.parseInt(map.getOrDefault("layer", "0"));

        switch (type) {
            case "rectangle":
                return new Rectangle(
                    Double.parseDouble(map.getOrDefault("width","0")),
                    Double.parseDouble(map.getOrDefault("height","0")),
                    color, layer
                );
            case "circle":
                return new Circle(
                    Double.parseDouble(map.getOrDefault("radius","0")),
                    color, layer
                );
            case "triangle":
                return new Triangle(
                    Double.parseDouble(map.getOrDefault("a","0")),
                    Double.parseDouble(map.getOrDefault("b","0")),
                    Double.parseDouble(map.getOrDefault("c","0")),
                    color, layer
                );
            case "cube":
                return new Cube(
                    Double.parseDouble(map.getOrDefault("edge","0")),
                    color, layer
                );
            case "sphere":
                return new Sphere(
                    Double.parseDouble(map.getOrDefault("radius","0")),
                    color, layer
                );
            default:
                throw new IllegalArgumentException("Unknown shape type: " + type);
        }
    }
}

class ShapePricing {
    private final MetricCalculator calc = new MetricCalculator();

    public double price(Shape shape) {
        switch (shape.getKind()) {
            case RECTANGLE: {
                double area = calc.compute(shape, Metric.AREA);
                return 0.5 * area + shape.getLayer() * 2;
            }
            case CIRCLE: {
                double area = calc.compute(shape, Metric.AREA);
                double diag = calc.compute(shape, Metric.DIAGONAL);
                return 0.6 * area + 0.1 * diag;
            }
            case TRIANGLE: {
                double per = calc.compute(shape, Metric.PERIMETER);
                return per * 0.8;
            }
            case CUBE: {
                double vol = calc.compute(shape, Metric.VOLUME);
                return 1.2 * vol;
            }
            case SPHERE: {
                double vol = calc.compute(shape, Metric.VOLUME);
                return 1.0 * vol + 10;
            }
            default: return 0;
        }
    }
}

class LegendBuilder {
    public String legendSymbol(Shape shape) {
        switch (shape.getKind()) {
            case RECTANGLE: return "▭";
            case CIRCLE:    return "◯";
            case TRIANGLE:  return "△";
            case CUBE:      return "⬛";
            case SPHERE:    return "◯";
            default:        return "?";
        }
    }
}

class CollisionEngine {
    public BoundingBox boundingBox(Shape shape) {
        switch (shape.getKind()) {
            case RECTANGLE: {
                Rectangle r = (Rectangle) shape;
                return new BoundingBox(r.getWidth(), r.getHeight());
            }
            case CIRCLE: {
                Circle c = (Circle) shape;
                double d = 2 * c.getRadius();
                return new BoundingBox(d, d);
            }
            case TRIANGLE: {
                Triangle t = (Triangle) shape;
                // naive placeholder: longest side × (average of other sides)
                double max = Math.max(t.getA(), Math.max(t.getB(), t.getC()));
                double avg = (t.getA() + t.getB() + t.getC() - max) / 2.0;
                return new BoundingBox(max, avg);
            }
            case CUBE: {
                Cube cube = (Cube) shape;
                return new BoundingBox(cube.getEdge(), cube.getEdge());
            }
            case SPHERE: {
                Sphere s = (Sphere) shape;
                double d = 2 * s.getRadius();
                return new BoundingBox(d, d);
            }
            default: return new BoundingBox(0, 0);
        }
    }

    public boolean overlaps(Shape a, Shape b) {
        BoundingBox A = boundingBox(a);
        BoundingBox B = boundingBox(b);
        return (A.width * A.height) > 0 && (B.width * B.height) > 0;
    }
}

class ShapeReport {
    private final MetricCalculator calc = new MetricCalculator();
    private final ShapeSerializer ser = new ShapeSerializer();
    private final ShapeRenderer rnd = new ShapeRenderer();
    private final CollisionEngine col = new CollisionEngine();
    private final ShapePricing price = new ShapePricing();
    private final LegendBuilder legend = new LegendBuilder();

    public String summarize(java.util.List<Shape> shapes) {
        StringBuilder sb = new StringBuilder();
        sb.append("=== Shape Report (OCP-violating) ===\n");
        for (Shape s : shapes) {
            sb.append("ID ").append(s.getId())
              .append(" ").append(s.getKind())
              .append(" color=").append(s.getColor())
              .append(" layer=").append(s.getLayer()).append("\n");

            sb.append("  CSV: ").append(ser.toCsvRow(s)).append("\n");
            sb.append("  SVG: ").append(rnd.renderPseudoSvg(s)).append("\n");
            sb.append("  Legend: ").append(legend.legendSymbol(s)).append("\n");

            sb.append("  Metrics: ");
            sb.append(" area=").append(calc.compute(s, Metric.AREA));
            sb.append(" perim=").append(calc.compute(s, Metric.PERIMETER));
            sb.append(" diag=").append(calc.compute(s, Metric.DIAGONAL));
            if (s instanceof ThreeDShape) {
                sb.append(" vol=").append(calc.compute(s, Metric.VOLUME));
            }
            sb.append("\n");

            sb.append("  BBox: ").append(col.boundingBox(s)).append("\n");
            sb.append("  Price: ").append(price.price(s)).append("\n\n");
        }
        return sb.toString();
    }
}

import java.util.*;

enum CharacterType { WARRIOR, MAGE, ARCHER, ROGUE }
enum SkillType { BASIC, SPECIAL, SUPPORT }
enum WeaponType { SWORD, STAFF, BOW, DAGGER }
enum PetType { WOLF, FAIRY, HAWK, SHADOW_CAT }

class Stats {
    int hp, mp, atk, mag, def, res, spd, crit;
    Stats(int hp,int mp,int atk,int mag,int def,int res,int spd,int crit){
        this.hp=hp; this.mp=mp; this.atk=atk; this.mag=mag; this.def=def; this.res=res; this.spd=spd; this.crit=crit;
    }
    Stats copy(){ return new Stats(hp,mp,atk,mag,def,res,spd,crit); }
}

class Skill {
    final String name; final SkillType type; final int cost;
    Skill(String n, SkillType t, int c){ name=n; type=t; cost=c; }
}

class Weapon {
    final String name; final WeaponType type; final int power;
    Weapon(String n, WeaponType t, int p){ name=n; type=t; power=p; }
}

class Pet {
    final String name; final PetType type; final int bond;
    Pet(String n, PetType t, int b){ name=n; type=t; bond=b; }
}

class Enemy {
    final String name; final Stats stats;
    Enemy(String n, Stats s){ name=n; stats=s; }
}

class GameCharacter {
    final String name; final CharacterType type; final int level; final Stats stats;
    final List<Skill> skills; final Weapon weapon; final Pet pet;
    GameCharacter(String n, CharacterType t, int lvl, Stats s, List<Skill> k, Weapon w, Pet p){
        name=n; type=t; level=lvl; stats=s; skills=k; weapon=w; pet=p;
    }
}

class PetBoostSystem {
    int offenseBoost(GameCharacter c){
        switch(c.pet.type){
            case WOLF: return (int)(c.stats.atk * Math.min(0.25, 0.05 + c.pet.bond/100.0));
            case FAIRY: return (int)(c.stats.mag * Math.min(0.25, 0.05 + c.pet.bond/120.0));
            case HAWK: return c.stats.spd/3 + c.pet.bond/6;
            case SHADOW_CAT: return 5 + c.pet.bond/5;
        }
        return 0;
    }
    int defenseBoost(GameCharacter c){
        switch(c.pet.type){
            case WOLF: return c.stats.def/6;
            case FAIRY: return c.stats.res/4;
            case HAWK: return c.stats.spd/6;
            case SHADOW_CAT: return 3;
        }
        return 0;
    }
    boolean petAssist(GameCharacter c){
        switch(c.pet.type){
            case WOLF: return new Random().nextInt(100) < Math.min(35, 10 + c.pet.bond/3);
            case FAIRY: return new Random().nextInt(100) < Math.min(40, 15 + c.pet.bond/2);
            case HAWK: return new Random().nextInt(100) < Math.min(30, 8 + c.pet.bond/4);
            case SHADOW_CAT: return new Random().nextInt(100) < Math.min(45, 12 + c.pet.bond/2);
        }
        return false;
    }
    int petAssistDamage(GameCharacter c){
        switch(c.pet.type){
            case WOLF: return 6 + c.pet.bond/4;
            case FAIRY: return 4 + c.pet.bond/5;
            case HAWK: return 5 + c.pet.bond/6;
            case SHADOW_CAT: return 7 + c.pet.bond/5;
        }
        return 0;
    }
    int petAssistHeal(GameCharacter c){
        switch(c.pet.type){
            case FAIRY: return 8 + c.pet.bond/3;
            default: return 0;
        }
    }
}

class WeaponRuleSet {
    int applyWeapon(GameCharacter c, int base){
        switch(c.weapon.type){
            case SWORD: return base + c.weapon.power + c.stats.atk/4;
            case STAFF: return base + c.weapon.power/2 + c.stats.mag/2;
            case BOW: return base + c.weapon.power + c.stats.spd/3;
            case DAGGER: return base + c.weapon.power + c.stats.spd/2;
        }
        return base;
    }
    int critChance(GameCharacter c){
        switch(c.weapon.type){
            case SWORD: return 8 + c.stats.crit;
            case STAFF: return 5 + c.stats.crit/2;
            case BOW: return 15 + c.stats.crit;
            case DAGGER: return 18 + c.stats.crit;
        }
        return 0;
    }
}

class DamageCalculator {
    final Random rng = new Random();
    final WeaponRuleSet wr = new WeaponRuleSet();
    final PetBoostSystem pets = new PetBoostSystem();

    int calc(GameCharacter c, Skill s, Enemy e){
        int base;
        switch(c.type){
            case WARRIOR:
                base = (int)(c.stats.atk * (1.1 + c.level*0.03)) - e.stats.def/3;
                if(s.type==SkillType.SPECIAL) base += 12;
                break;
            case MAGE:
                base = c.stats.mag*2 + (s.type==SkillType.SPECIAL?18:0) - e.stats.res/2;
                break;
            case ARCHER:
                base = c.stats.atk + c.stats.spd/2 + (s.type==SkillType.SPECIAL?10:0) - e.stats.def/4;
                break;
            case ROGUE:
                base = c.stats.atk + c.stats.spd + (s.type==SkillType.SPECIAL?14:0) - e.stats.def/5;
                break;
            default:
                base = 0;
        }
        base = wr.applyWeapon(c, base);
        base += pets.offenseBoost(c);
        if (pets.petAssist(c)) base += pets.petAssistDamage(c);
        int critChance = wr.critChance(c) + (c.type==CharacterType.ARCHER?10:0);
        if (rng.nextInt(100) < critChance) base *= 2;
        return Math.max(0, base);
    }
}

class HealCalculator {
    final PetBoostSystem pets = new PetBoostSystem();
    int heal(GameCharacter c, Skill s){
        int amt;
        switch(c.type){
            case WARRIOR: amt = c.stats.atk/3 + 6; break;
            case MAGE: amt = c.stats.mag + 14; break;
            case ARCHER: amt = c.stats.atk/4 + c.stats.spd/5; break;
            case ROGUE: amt = c.stats.atk/2; break;
            default: amt = 0;
        }
        if (s.type==SkillType.SPECIAL) amt += 6;
        amt += pets.defenseBoost(c)/2 + pets.petAssistHeal(c);
        return Math.max(0, amt);
    }
}

class LootCalculator {
    int gold(GameCharacter c, Enemy e){
        switch(c.type){
            case WARRIOR: return 10 + c.level + e.stats.def/5;
            case MAGE: return 9 + c.level*2 + e.stats.res/4;
            case ARCHER: return 11 + c.level + e.stats.def/6;
            case ROGUE: return 14 + c.level;
        }
        return 0;
    }
}

class TargetingSystem {
    Enemy pick(List<Enemy> enemies){
        Enemy t = enemies.get(0);
        for(Enemy e: enemies) if(e.stats.hp < t.stats.hp) t=e;
        return t;
    }
}

class SkillSelector {
    Skill choose(GameCharacter c){
        for(Skill s: c.skills) if(s.type!=SkillType.BASIC) return s;
        return c.skills.get(0);
    }
}

class TurnEngine {
    final DamageCalculator dmg=new DamageCalculator();
    final HealCalculator healCalc=new HealCalculator();
    final LootCalculator loot=new LootCalculator();
    final TargetingSystem targeting=new TargetingSystem();
    final SkillSelector selector=new SkillSelector();

    void turn(List<GameCharacter> party, List<Enemy> enemies){
        for(GameCharacter c: party){
            Skill s = selector.choose(c);
            if(s.type==SkillType.SUPPORT){
                int h = healCalc.heal(c,s);
                c.stats.hp += h;
                continue;
            }
            Enemy target = targeting.pick(enemies);
            int d = dmg.calc(c,s,target);
            target.stats.hp = Math.max(0, target.stats.hp - d);
        }
    }
    int totalGold(List<GameCharacter> party, Enemy e){
        int g=0; for(GameCharacter c: party) g+=loot.gold(c,e); return g;
    }
}

