import kotlin.math.*

abstract class Entity {
    companion object {
        private var NEXT_ID = 1L
    }
    val id: Long = NEXT_ID++
}

abstract class GraphicObject(val color: String, val layer: Int) : Entity()

enum class ShapeKind { RECTANGLE, CIRCLE, TRIANGLE, CUBE, SPHERE }

abstract class Shape(val kind: ShapeKind, color: String, layer: Int) : GraphicObject(color, layer)
abstract class TwoDShape(kind: ShapeKind, color: String, layer: Int) : Shape(kind, color, layer)
abstract class ThreeDShape(kind: ShapeKind, color: String, layer: Int) : Shape(kind, color, layer)

class Rectangle(val width: Double, val height: Double, color: String, layer: Int)
    : TwoDShape(ShapeKind.RECTANGLE, color, layer)

class Circle(val radius: Double, color: String, layer: Int)
    : TwoDShape(ShapeKind.CIRCLE, color, layer)

class Triangle(val a: Double, val b: Double, val c: Double, color: String, layer: Int)
    : TwoDShape(ShapeKind.TRIANGLE, color, layer)

class Cube(val edge: Double, color: String, layer: Int)
    : ThreeDShape(ShapeKind.CUBE, color, layer)

class Sphere(val radius: Double, color: String, layer: Int)
    : ThreeDShape(ShapeKind.SPHERE, color, layer)

enum class Metric { AREA, PERIMETER, VOLUME, DIAGONAL, BOUNDING_BOX_WIDTH }

data class BoundingBox(val width: Double, val height: Double) {
    override fun toString(): String = "BBox(${width}x$height)"
}

class MetricCalculator {
    fun compute(shape: Shape, metric: Metric): Double {
        return when (shape.kind) {
            ShapeKind.RECTANGLE -> {
                val r = shape as Rectangle
                when (metric) {
                    Metric.AREA -> r.width * r.height
                    Metric.PERIMETER -> 2 * (r.width + r.height)
                    Metric.DIAGONAL -> hypot(r.width, r.height)
                    Metric.BOUNDING_BOX_WIDTH -> r.width
                    Metric.VOLUME -> 0.0
                }
            }
            ShapeKind.CIRCLE -> {
                val c = shape as Circle
                when (metric) {
                    Metric.AREA -> PI * c.radius * c.radius
                    Metric.PERIMETER -> 2 * PI * c.radius
                    Metric.DIAGONAL -> 2 * c.radius
                    Metric.BOUNDING_BOX_WIDTH -> 2 * c.radius
                    Metric.VOLUME -> 0.0
                }
            }
            ShapeKind.TRIANGLE -> {
                val t = shape as Triangle
                val s = (t.a + t.b + t.c) / 2.0
                when (metric) {
                    Metric.AREA -> sqrt(max(0.0, s * (s - t.a) * (s - t.b) * (s - t.c)))
                    Metric.PERIMETER -> t.a + t.b + t.c
                    Metric.DIAGONAL -> maxOf(t.a, t.b, t.c)
                    Metric.BOUNDING_BOX_WIDTH -> maxOf(t.a, t.b, t.c)
                    Metric.VOLUME -> 0.0
                }
            }
            ShapeKind.CUBE -> {
                val cube = shape as Cube
                when (metric) {
                    Metric.AREA -> 6 * cube.edge * cube.edge
                    Metric.PERIMETER -> 12 * cube.edge
                    Metric.VOLUME -> cube.edge.pow(3)
                    Metric.DIAGONAL -> sqrt(3.0) * cube.edge
                    Metric.BOUNDING_BOX_WIDTH -> cube.edge
                }
            }
            ShapeKind.SPHERE -> {
                val s = shape as Sphere
                when (metric) {
                    Metric.AREA -> 4 * PI * s.radius * s.radius
                    Metric.PERIMETER -> 0.0
                    Metric.VOLUME -> (4.0 / 3.0) * PI * s.radius.pow(3)
                    Metric.DIAGONAL -> 2 * s.radius
                    Metric.BOUNDING_BOX_WIDTH -> 2 * s.radius
                }
            }
        }
    }
}

class ShapeValidator {
    fun isValid(shape: Shape): Boolean {
        return when (shape.kind) {
            ShapeKind.RECTANGLE -> {
                val r = shape as Rectangle
                r.width > 0 && r.height > 0
            }
            ShapeKind.CIRCLE -> (shape as Circle).radius > 0
            ShapeKind.TRIANGLE -> {
                val t = shape as Triangle
                t.a > 0 && t.b > 0 && t.c > 0 &&
                t.a + t.b > t.c && t.a + t.c > t.b && t.b + t.c > t.a
            }
            ShapeKind.CUBE -> (shape as Cube).edge > 0
            ShapeKind.SPHERE -> (shape as Sphere).radius > 0
        }
    }
}

class ShapeRenderer {
    fun renderPseudoSvg(shape: Shape): String {
        return when (shape.kind) {
            ShapeKind.RECTANGLE -> {
                val r = shape as Rectangle
                "<rect w=\"${r.width}\" h=\"${r.height}\" fill=\"${shape.color}\" layer=\"${shape.layer}\"/>"
            }
            ShapeKind.CIRCLE -> {
                val c = shape as Circle
                "<circle r=\"${c.radius}\" fill=\"${shape.color}\" layer=\"${shape.layer}\"/>"
            }
            ShapeKind.TRIANGLE -> {
                val t = shape as Triangle
                "<polygon a=\"${t.a}\" b=\"${t.b}\" c=\"${t.c}\" fill=\"${shape.color}\" layer=\"${shape.layer}\"/>"
            }
            ShapeKind.CUBE -> {
                val cube = shape as Cube
                "<cube edge=\"${cube.edge}\" materialColor=\"${shape.color}\" layer=\"${shape.layer}\"/>"
            }
            ShapeKind.SPHERE -> {
                val s = shape as Sphere
                "<sphere r=\"${s.radius}\" materialColor=\"${shape.color}\" layer=\"${shape.layer}\"/>"
            }
        }
    }
}

class ShapeSerializer {
    fun toCsvRow(shape: Shape): String {
        return when (shape.kind) {
            ShapeKind.RECTANGLE -> {
                val r = shape as Rectangle
                "rectangle,${r.width},${r.height},${shape.color},${shape.layer}"
            }
            ShapeKind.CIRCLE -> {
                val c = shape as Circle
                "circle,${c.radius},${shape.color},${shape.layer}"
            }
            ShapeKind.TRIANGLE -> {
                val t = shape as Triangle
                "triangle,${t.a},${t.b},${t.c},${shape.color},${shape.layer}"
            }
            ShapeKind.CUBE -> {
                val cube = shape as Cube
                "cube,${cube.edge},${shape.color},${shape.layer}"
            }
            ShapeKind.SPHERE -> {
                val s = shape as Sphere
                "sphere,${s.radius},${shape.color},${shape.layer}"
            }
        }
    }
}

class ShapeFactory {
    fun create(spec: String): Shape {
        val parts = spec.split(";")
        val type = parts[0].trim().lowercase()
        val map = parts.drop(1).associate {
            val (k, v) = it.split("=")
            k.trim().lowercase() to v.trim()
        }
        val color = map.getOrDefault("color", "black")
        val layer = map.getOrDefault("layer", "0").toInt()

        return when (type) {
            "rectangle" -> Rectangle(
                map.getOrDefault("width", "0").toDouble(),
                map.getOrDefault("height", "0").toDouble(),
                color, layer
            )
            "circle" -> Circle(
                map.getOrDefault("radius", "0").toDouble(),
                color, layer
            )
            "triangle" -> Triangle(
                map.getOrDefault("a", "0").toDouble(),
                map.getOrDefault("b", "0").toDouble(),
                map.getOrDefault("c", "0").toDouble(),
                color, layer
            )
            "cube" -> Cube(
                map.getOrDefault("edge", "0").toDouble(),
                color, layer
            )
            "sphere" -> Sphere(
                map.getOrDefault("radius", "0").toDouble(),
                color, layer
            )
            else -> throw IllegalArgumentException("Unknown shape type: $type")
        }
    }
}

class ShapePricing {
    private val calc = MetricCalculator()
    fun price(shape: Shape): Double = when (shape.kind) {
        ShapeKind.RECTANGLE -> 0.5 * calc.compute(shape, Metric.AREA) + shape.layer * 2
        ShapeKind.CIRCLE -> 0.6 * calc.compute(shape, Metric.AREA) + 0.1 * calc.compute(shape, Metric.DIAGONAL)
        ShapeKind.TRIANGLE -> 0.8 * calc.compute(shape, Metric.PERIMETER)
        ShapeKind.CUBE -> 1.2 * calc.compute(shape, Metric.VOLUME)
        ShapeKind.SPHERE -> 1.0 * calc.compute(shape, Metric.VOLUME) + 10
    }
}

class LegendBuilder {
    fun legendSymbol(shape: Shape): String = when (shape.kind) {
        ShapeKind.RECTANGLE -> "▭"
        ShapeKind.CIRCLE -> "◯"
        ShapeKind.TRIANGLE -> "△"
        ShapeKind.CUBE -> "⬛"
        ShapeKind.SPHERE -> "◯"
    }
}

class CollisionEngine {
    fun boundingBox(shape: Shape): BoundingBox = when (shape.kind) {
        ShapeKind.RECTANGLE -> {
            val r = shape as Rectangle
            BoundingBox(r.width, r.height)
        }
        ShapeKind.CIRCLE -> {
            val c = shape as Circle
            val d = 2 * c.radius
            BoundingBox(d, d)
        }
        ShapeKind.TRIANGLE -> {
            val t = shape as Triangle
            val max = maxOf(t.a, t.b, t.c)
            val avg = (t.a + t.b + t.c - max) / 2.0
            BoundingBox(max, avg)
        }
        ShapeKind.CUBE -> {
            val cube = shape as Cube
            BoundingBox(cube.edge, cube.edge)
        }
        ShapeKind.SPHERE -> {
            val s = shape as Sphere
            val d = 2 * s.radius
            BoundingBox(d, d)
        }
    }

    fun overlaps(a: Shape, b: Shape): Boolean {
        val A = boundingBox(a)
        val B = boundingBox(b)
        return A.width * A.height > 0 && B.width * B.height > 0
    }
}

class ShapeReport {
    private val calc = MetricCalculator()
    private val ser = ShapeSerializer()
    private val rnd = ShapeRenderer()
    private val col = CollisionEngine()
    private val price = ShapePricing()
    private val legend = LegendBuilder()

    fun summarize(shapes: List<Shape>): String {
        val sb = StringBuilder("=== Shape Report (OCP-violating) ===\n")
        for (s in shapes) {
            sb.append("ID ${s.id} ${s.kind} color=${s.color} layer=${s.layer}\n")
            sb.append("  CSV: ${ser.toCsvRow(s)}\n")
            sb.append("  SVG: ${rnd.renderPseudoSvg(s)}\n")
            sb.append("  Legend: ${legend.legendSymbol(s)}\n")
            sb.append("  Metrics: area=${calc.compute(s, Metric.AREA)} perim=${calc.compute(s, Metric.PERIMETER)} diag=${calc.compute(s, Metric.DIAGONAL)}")
            if (s is ThreeDShape) sb.append(" vol=${calc.compute(s, Metric.VOLUME)}")
            sb.append("\n")
            sb.append("  BBox: ${col.boundingBox(s)}\n")
            sb.append("  Price: ${price.price(s)}\n\n")
        }
        return sb.toString()
    }
}

import java.util.*

enum class CharacterType { WARRIOR, MAGE, ARCHER, ROGUE }
enum class SkillType { BASIC, SPECIAL, SUPPORT }
enum class WeaponType { SWORD, STAFF, BOW, DAGGER }
enum class PetType { WOLF, FAIRY, HAWK, SHADOW_CAT }

data class Stats(var hp: Int, var mp: Int, var atk: Int, var mag: Int, var def: Int, var res: Int, var spd: Int, var crit: Int) {
    fun copy() = Stats(hp, mp, atk, mag, def, res, spd, crit)
}

data class Skill(val name: String, val type: SkillType, val cost: Int)
data class Weapon(val name: String, val type: WeaponType, val power: Int)
data class Pet(val name: String, val type: PetType, val bond: Int)
data class Enemy(val name: String, val stats: Stats)

data class GameCharacter(
    val name: String,
    val type: CharacterType,
    val level: Int,
    val stats: Stats,
    val skills: List<Skill>,
    val weapon: Weapon,
    val pet: Pet
)

class PetBoostSystem {
    fun offenseBoost(c: GameCharacter): Int = when (c.pet.type) {
        PetType.WOLF -> (c.stats.atk * minOf(0.25, 0.05 + c.pet.bond / 100.0)).toInt()
        PetType.FAIRY -> (c.stats.mag * minOf(0.25, 0.05 + c.pet.bond / 120.0)).toInt()
        PetType.HAWK -> c.stats.spd / 3 + c.pet.bond / 6
        PetType.SHADOW_CAT -> 5 + c.pet.bond / 5
    }

    fun defenseBoost(c: GameCharacter): Int = when (c.pet.type) {
        PetType.WOLF -> c.stats.def / 6
        PetType.FAIRY -> c.stats.res / 4
        PetType.HAWK -> c.stats.spd / 6
        PetType.SHADOW_CAT -> 3
    }

    fun petAssist(c: GameCharacter): Boolean = when (c.pet.type) {
        PetType.WOLF -> Random().nextInt(100) < minOf(35, 10 + c.pet.bond / 3)
        PetType.FAIRY -> Random().nextInt(100) < minOf(40, 15 + c.pet.bond / 2)
        PetType.HAWK -> Random().nextInt(100) < minOf(30, 8 + c.pet.bond / 4)
        PetType.SHADOW_CAT -> Random().nextInt(100) < minOf(45, 12 + c.pet.bond / 2)
    }

    fun petAssistDamage(c: GameCharacter): Int = when (c.pet.type) {
        PetType.WOLF -> 6 + c.pet.bond / 4
        PetType.FAIRY -> 4 + c.pet.bond / 5
        PetType.HAWK -> 5 + c.pet.bond / 6
        PetType.SHADOW_CAT -> 7 + c.pet.bond / 5
    }

    fun petAssistHeal(c: GameCharacter): Int = when (c.pet.type) {
        PetType.FAIRY -> 8 + c.pet.bond / 3
        else -> 0
    }
}

class WeaponRuleSet {
    fun applyWeapon(c: GameCharacter, base: Int): Int = when (c.weapon.type) {
        WeaponType.SWORD -> base + c.weapon.power + c.stats.atk / 4
        WeaponType.STAFF -> base + c.weapon.power / 2 + c.stats.mag / 2
        WeaponType.BOW -> base + c.weapon.power + c.stats.spd / 3
        WeaponType.DAGGER -> base + c.weapon.power + c.stats.spd / 2
    }

    fun critChance(c: GameCharacter): Int = when (c.weapon.type) {
        WeaponType.SWORD -> 8 + c.stats.crit
        WeaponType.STAFF -> 5 + c.stats.crit / 2
        WeaponType.BOW -> 15 + c.stats.crit
        WeaponType.DAGGER -> 18 + c.stats.crit
    }
}

class DamageCalculator {
    private val rng = Random()
    private val wr = WeaponRuleSet()
    private val pets = PetBoostSystem()

    fun calc(c: GameCharacter, s: Skill, e: Enemy): Int {
        var base = when (c.type) {
            CharacterType.WARRIOR -> (c.stats.atk * (1.1 + c.level * 0.03)).toInt() - e.stats.def / 3 + if (s.type == SkillType.SPECIAL) 12 else 0
            CharacterType.MAGE -> c.stats.mag * 2 + if (s.type == SkillType.SPECIAL) 18 else 0 - e.stats.res / 2
            CharacterType.ARCHER -> c.stats.atk + c.stats.spd / 2 + if (s.type == SkillType.SPECIAL) 10 else 0 - e.stats.def / 4
            CharacterType.ROGUE -> c.stats.atk + c.stats.spd + if (s.type == SkillType.SPECIAL) 14 else 0 - e.stats.def / 5
        }
        base = wr.applyWeapon(c, base)
        base += pets.offenseBoost(c)
        if (pets.petAssist(c)) base += pets.petAssistDamage(c)
        val critChance = wr.critChance(c) + if (c.type == CharacterType.ARCHER) 10 else 0
        if (rng.nextInt(100) < critChance) base *= 2
        return maxOf(0, base)
    }
}

class HealCalculator {
    private val pets = PetBoostSystem()
    fun heal(c: GameCharacter, s: Skill): Int {
        var amt = when (c.type) {
            CharacterType.WARRIOR -> c.stats.atk / 3 + 6
            CharacterType.MAGE -> c.stats.mag + 14
            CharacterType.ARCHER -> c.stats.atk / 4 + c.stats.spd / 5
            CharacterType.ROGUE -> c.stats.atk / 2
        }
        if (s.type == SkillType.SPECIAL) amt += 6
        amt += pets.defenseBoost(c) / 2 + pets.petAssistHeal(c)
        return maxOf(0, amt)
    }
}

class LootCalculator {
    fun gold(c: GameCharacter, e: Enemy): Int = when (c.type) {
        CharacterType.WARRIOR -> 10 + c.level + e.stats.def / 5
        CharacterType.MAGE -> 9 + c.level * 2 + e.stats.res / 4
        CharacterType.ARCHER -> 11 + c.level + e.stats.def / 6
        CharacterType.ROGUE -> 14 + c.level
    }
}

class TargetingSystem {
    fun pick(enemies: List<Enemy>): Enemy {
        var t = enemies[0]
        for (e in enemies) if (e.stats.hp < t.stats.hp) t = e
        return t
    }
}

class SkillSelector {
    fun choose(c: GameCharacter): Skill = c.skills.firstOrNull { it.type != SkillType.BASIC } ?: c.skills[0]
}

class TurnEngine {
    private val dmg = DamageCalculator()
    private val healCalc = HealCalculator()
    private val loot = LootCalculator()
    private val targeting = TargetingSystem()
    private val selector = SkillSelector()

    fun turn(party: List<GameCharacter>, enemies: MutableList<Enemy>) {
        for (c in party) {
            val s = selector.choose(c)
            if (s.type == SkillType.SUPPORT) {
                val h = healCalc.heal(c, s)
                c.stats.hp += h
                continue
            }
            val target = targeting.pick(enemies)
            val d = dmg.calc(c, s, target)
            target.stats.hp = maxOf(0, target.stats.hp - d)
        }
    }

    fun totalGold(party: List<GameCharacter>, e: Enemy): Int = party.sumOf { loot.gold(it, e) }
}

