enum class CharacterType {
    WARRIOR,
    MAGE,
    ARCHER
}

enum class SkillType {
    BASIC,
    SPECIAL
}

class GameCharacter(
    private val name: String,
    private val type: CharacterType,
    private val baseAttack: Int,
    private val level: Int
) {
    fun getName() = name
    fun getType() = type
    fun getBaseAttack() = baseAttack
    fun getLevel() = level
}

class Skill(
    private val type: SkillType,
    private val name: String
) {
    fun getType() = type
    fun getName() = name
}

class Enemy(
    private val name: String,
    private val armor: Int,
    private val resistance: Int
) {
    fun getName() = name
    fun getArmor() = armor
    fun getResistance() = resistance
}

class DamageCalculator {
    private val rng = Random.Default

    fun calculateDamage(c: GameCharacter, s: Skill, e: Enemy): Int {
        return when (c.getType()) {
            CharacterType.WARRIOR -> {
                var raw = (c.getBaseAttack() * (1.2 + c.getLevel() * 0.05)).toInt()
                if (s.getType() == SkillType.SPECIAL) raw = (raw * 1.5).toInt()
                raw -= e.getArmor()
                maxOf(raw, 0)
            }
            CharacterType.MAGE -> {
                var raw = c.getBaseAttack() + (c.getLevel() * 3.5).toInt()
                if (s.getType() == SkillType.SPECIAL) raw += 25
                raw -= e.getResistance()
                maxOf(raw, 0)
            }
            CharacterType.ARCHER -> {
                var raw = c.getBaseAttack()
                val crit = rng.nextInt(100) < (20 + c.getLevel())
                if (crit) raw *= 2
                if (s.getType() == SkillType.SPECIAL) raw += 10
                raw -= (e.getArmor() * 0.5).toInt()
                maxOf(raw, 0)
            }
        }
    }
}

class LootCalculator {
    fun calculateGold(c: GameCharacter, e: Enemy): Int {
        return when (c.getType()) {
            CharacterType.WARRIOR -> 10 + c.getLevel() + e.getArmor() / 5
            CharacterType.MAGE -> 8 + c.getLevel() * 2 + e.getResistance() / 4
            CharacterType.ARCHER -> 9 + (c.getLevel() * 1.5).roundToInt()
        }
    }
}

