class Cashier:
    def __init__(self):
        self.prices = PriceCalculator()
        self.taxes = TaxCalculator()
        self.promos = PromotionEngine()

    def total(self, order):
        sum_ = 0.0
        for item in order.items():
            base = self.prices.price(item)
            discount = self.promos.discount(item)
            taxed = (base - discount) * (1.0 + self.taxes.taxFor(item))
            sum_ += taxed
        return round(sum_, 2)


