class Enemy:
    def __init__(self, name: str, armor: int, resistance: int):
        self._name = name
        self._armor = armor
        self._resistance = resistance

    def get_name(self):
        return self._name

    def get_armor(self):
        return self._armor

    def get_resistance(self):
        return self._resistance


class DamageCalculator:
    def __init__(self):
        self._rng = random.Random()

    def calculate_damage(self, c: GameCharacter, s: Skill, e: Enemy) -> int:
        if c.get_type() == CharacterType.WARRIOR:
            raw = int(c.get_base_attack() * (1.2 + c.get_level() * 0.05))
            if s.get_type() == SkillType.SPECIAL:
                raw = int(raw * 1.5)
            raw -= e.get_armor()
            return max(raw, 0)
        elif c.get_type() == CharacterType.MAGE:
            raw = c.get_base_attack() + int(c.get_level() * 3.5)
            if s.get_type() == SkillType.SPECIAL:
                raw += 25
            raw -= e.get_resistance()
            return max(raw, 0)
        elif c.get_type() == CharacterType.ARCHER:
            raw = c.get_base_attack()
            crit = self._rng.randint(0, 99) < (20 + c.get_level())
            if crit:
                raw *= 2
            if s.get_type() == SkillType.SPECIAL:
                raw += 10
            raw -= int(e.get_armor() * 0.5)
            return max(raw, 0)
        else:
            raise ValueError("Unknown type")


class LootCalculator:
    def calculate_gold(self, c: GameCharacter, e: Enemy) -> int:
        if c.get_type() == CharacterType.WARRIOR:
            return 10 + c.get_level() + e.get_armor() // 5
        elif c.get_type() == CharacterType.MAGE:
            return 8 + c.get_level() * 2 + e.get_resistance() // 4
        elif c.get_type() == CharacterType.ARCHER:
            return 9 + round(c.get_level() * 1.5)
        else:
            raise ValueError("Unknown type")

