            base = self._prices.price(item)
            discount = self._promos.discount(item)
            taxed = (base - discount) * (1.0 + self._taxes.tax_for(item))
            sum_ += taxed
        return round(sum_, 2)


class ReceiptPrinter:
    def __init__(self):
        self._prices = PriceCalculator()
        self._taxes = TaxCalculator()
        self._promos = PromotionEngine()
        self._nutrition = NutritionCalculator()

    def print(self, order: Order):
        print("Customer:", order.customer())
        for item in order.items():
            base = self._prices.price(item)
            discount = self._promos.discount(item)
            tax_rate = self._taxes.tax_for(item)
            kcal = self._nutrition.calories(item)
            print(f"{item.get_name()} ({item.get_type().name} {item.get_size().name}) "
                  f"base ${base} disc ${discount} tax {int(tax_rate*100)}% kcal {kcal}")

from enum import Enum
from typing import List


class DeviceType(Enum):
    LIGHT = 1
    THERMOSTAT = 2
    DOOR_LOCK = 3
    CAMERA = 4
    SPRINKLER = 5


class RoomType(Enum):
    LIVING = 1
    KITCHEN = 2
    BEDROOM = 3
    GARDEN = 4


class Mode(Enum):
    ECO = 1
    COMFORT = 2
    AWAY = 3
    NIGHT = 4


class SmartDevice:
    def __init__(self, id_: str, type_: DeviceType):
        self._id = id_
        self._type = type_
        self._mode = Mode.ECO
        self._online = True

    def getId(self): return self._id
    def getType(self): return self._type
    def getMode(self): return self._mode
    def isOnline(self): return self._online
    def setMode(self, m: Mode): self._mode = m
    def setOnline(self, o: bool): self._online = o


class Room:
    def __init__(self, name: str, type_: RoomType):
        self._name = name
        self._type = type_
        self._devices: List[SmartDevice] = []

    def add(self, d: SmartDevice): self._devices.append(d)
    def getDevices(self): return self._devices
    def getName(self): return self._name
    def getType(self): return self._type


class ScheduleEntry:
    def __init__(self, device: SmartDevice, cron: str, action: str):
        self.device = device
        self.cron = cron
        self.action = action


class SmartHomeController:
    def turnOn(self, d: SmartDevice):
        if d.getType() == DeviceType.LIGHT: print("Light", d.getId(), "ON")
        elif d.getType() == DeviceType.THERMOSTAT: print("Thermostat", d.getId(), "heating")
        elif d.getType() == DeviceType.DOOR_LOCK: print("Lock", d.getId(), "stays locked")
        elif d.getType() == DeviceType.CAMERA: print("Camera", d.getId(), "recording")
        elif d.getType() == DeviceType.SPRINKLER: print("Sprinkler", d.getId(), "watering")

    def turnOff(self, d: SmartDevice):
        if d.getType() == DeviceType.LIGHT: print("Light", d.getId(), "OFF")
        elif d.getType() == DeviceType.THERMOSTAT: print("Thermostat", d.getId(), "idle")
        elif d.getType() == DeviceType.DOOR_LOCK: print("Lock", d.getId(), "remains locked")
        elif d.getType() == DeviceType.CAMERA: print("Camera", d.getId(), "standby")
        elif d.getType() == DeviceType.SPRINKLER: print("Sprinkler", d.getId(), "stopped")

    def setMode(self, d: SmartDevice, m: Mode):
        d.setMode(m)
        print(d.getType().name.capitalize(), d.getId(), "mode", m.name)

    def energyUsageKwh(self, d: SmartDevice, minutes: int) -> float:
        if d.getType() == DeviceType.LIGHT: return 0.012 * minutes
        elif d.getType() == DeviceType.THERMOSTAT: return 0.08 * minutes
        elif d.getType() == DeviceType.DOOR_LOCK: return 0.0002 * minutes
        elif d.getType() == DeviceType.CAMERA: return 0.01 * minutes
        elif d.getType() == DeviceType.SPRINKLER: return 0.03 * minutes
        return 0.0

    def deviceIcon(self, d: SmartDevice) -> str:
        return {
            DeviceType.LIGHT: "💡",
            DeviceType.THERMOSTAT: "🌡️",
            DeviceType.DOOR_LOCK: "🔒",
            DeviceType.CAMERA: "📷",
            DeviceType.SPRINKLER: "💧"
        }.get(d.getType(), "❓")

    def firmwareUpdateSteps(self, d: SmartDevice) -> List[str]:
        if d.getType() == DeviceType.LIGHT: return ["Ping", "Push FW", "Reboot"]
        elif d.getType() == DeviceType.THERMOSTAT: return ["Ping", "Backup Profile", "Push FW", "Recalibrate"]
        elif d.getType() == DeviceType.DOOR_LOCK: return ["Ping", "Secure Channel", "Push FW", "Reauth"]
        elif d.getType() == DeviceType.CAMERA: return ["Ping", "Push FW", "Restart Stream"]
        elif d.getType() == DeviceType.SPRINKLER: return ["Ping", "Push FW", "Valve Test"]
        return []


class NotificationService:
    def notifyOwner(self, d: SmartDevice, event: str):
        print("Notify:", d.getType().name.capitalize(), d.getId(), "->", event)


class DiagnosticsService:
    def health(self, d: SmartDevice) -> str:
        if d.getType() == DeviceType.LIGHT: return "OK" if d.isOnline() else "Bulb Offline"
        elif d.getType() == DeviceType.THERMOSTAT: return "OK" if d.isOnline() else "Sensor Offline"
        elif d.getType() == DeviceType.DOOR_LOCK: return "OK" if d.isOnline() else "Battery Low"
        elif d.getType() == DeviceType.CAMERA: return "OK" if d.isOnline() else "Stream Error"
        elif d.getType() == DeviceType.SPRINKLER: return "OK" if d.isOnline() else "Valve Error"
        return "Unknown"

    def maintenanceCostYearly(self, d: SmartDevice) -> float:
        return {
            DeviceType.LIGHT: 5.0,
            DeviceType.THERMOSTAT: 20.0,
            DeviceType.DOOR_LOCK: 12.0,
            DeviceType.CAMERA: 18.0,
            DeviceType.SPRINKLER: 15.0
        }.get(d.getType(), 0.0)


class SecurityPolicy:
    def actionAllowed(self, d: SmartDevice, action: str, userHome: bool) -> bool:
        if d.getType() == DeviceType.DOOR_LOCK:
            return action == "unlock" and userHome or action != "unlock"
        elif d.getType() == DeviceType.CAMERA:
            return True
        elif d.getType() in [DeviceType.THERMOSTAT, DeviceType.LIGHT]:
            return True
        elif d.getType() == DeviceType.SPRINKLER:
            return not (action == "on" and userHome)
        return False


class VoiceCommandProcessor:
    def __init__(self): self._ctl = SmartHomeController()
    def handle(self, phrase: str, d: SmartDevice):
        if d.getType() == DeviceType.LIGHT:
            if phrase.lower() == "lights on": self._ctl.turnOn(d)
            elif phrase.lower() == "lights off": self._ctl.turnOff(d)
            elif phrase.lower() == "night mode": self._ctl.setMode(d, Mode.NIGHT)
        elif d.getType() == DeviceType.THERMOSTAT:
            if phrase.lower() == "heat on": self._ctl.turnOn(d)
            elif phrase.lower() == "eco mode": self._ctl.setMode(d, Mode.ECO)
        elif d.getType() == DeviceType.DOOR_LOCK:
            if phrase.lower() == "lock door": self._ctl.turnOn(d)
        elif d.getType() == DeviceType.CAMERA:
            if phrase.lower() == "start recording": self._ctl.turnOn(d)
        elif d.getType() == DeviceType.SPRINKLER:
            if phrase.lower() == "water garden": self._ctl.turnOn(d)


class SceneManager:
    def __init__(self): self._ctl = SmartHomeController()
    def applyScene(self, name: str, devices: List[SmartDevice]):
        for d in devices:
            if name == "Evening":
                if d.getType() == DeviceType.LIGHT: self._ctl.turnOn(d); self._ctl.setMode(d, Mode.COMFORT)
                elif d.getType() == DeviceType.THERMOSTAT: self._ctl.setMode(d, Mode.COMFORT)
                elif d.getType() == DeviceType.CAMERA: self._ctl.turnOn(d)
                elif d.getType() == DeviceType.DOOR_LOCK: self._ctl.turnOn(d)
                elif d.getType() == DeviceType.SPRINKLER: self._ctl.turnOff(d)
            elif name == "Away":
                if d.getType() == DeviceType.LIGHT: self._ctl.turnOff(d)
                elif d.getType() == DeviceType.THERMOSTAT: self._ctl.setMode(d, Mode.AWAY)
                elif d.getType() == DeviceType.CAMERA: self._ctl.turnOn(d)
                elif d.getType() == DeviceType.DOOR_LOCK: self._ctl.turnOn(d)
                elif d.getType() == DeviceType.SPRINKLER: self._ctl.turnOff(d)


class EnergyEstimator:
    def __init__(self): self._ctl = SmartHomeController()
    def estimateRoom(self, room: Room, minutes: int) -> float:
