public class PaymentProcessor {
    private PayPalGateway paypalGateway;
    private StripeGateway stripeGateway;
    private SquareGateway squareGateway;
    private List<PaymentResult> transactionHistory;

    public PaymentProcessor() {
        this.paypalGateway = new PayPalGateway();
        this.stripeGateway = new StripeGateway();
        this.squareGateway = new SquareGateway();
        this.transactionHistory = new ArrayList<>();
    }

    public PaymentResult processTransaction(double amount, String currency, String gateway, CustomerInfo customer) {
        PaymentResult result = null;

        switch (gateway.toLowerCase()) {
            case "paypal":
                result = paypalGateway.processPayment(amount, currency, customer);
                break;
            case "stripe":
                result = stripeGateway.chargeCard(amount, currency, customer);
                break;
            case "square":
                result = squareGateway.createPayment(amount, currency, customer);
                break;
            default:
                result = new PaymentResult(false, null, "Unsupported payment gateway");
        }

        if (result != null) {
            transactionHistory.add(result);
            generateTransactionReport(result, gateway, customer);
        }

        return result;
    }

    public boolean processRefund(String transactionId, double amount, String gateway) {
        switch (gateway.toLowerCase()) {
            case "paypal":
                return paypalGateway.processRefund(transactionId, amount);
            case "stripe":
                return stripeGateway.processRefund(transactionId, amount);
            case "square":
                return squareGateway.processRefund(transactionId, amount);
            default:
                return false;
        }
    }

    private void generateTransactionReport(PaymentResult result, String gateway, CustomerInfo customer) {
        String timestamp = LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME);
        System.out.println("Transaction Report [" + timestamp + "]: Gateway=" + gateway + ", Customer=" + customer.getName() + ", Status=" + (result.isSuccess() ? "SUCCESS" : "FAILED"));
    }

    public List<PaymentResult> getTransactionHistory() {
        return new ArrayList<>(transactionHistory);
    }
}

