    public class PaymentProcessor
    {
        private readonly PayPalGateway _paypalGateway;
        private readonly StripeGateway _stripeGateway;
        private readonly SquareGateway _squareGateway;
        private readonly List<PaymentResult> _transactionHistory;

        public PaymentProcessor()
        {
            _paypalGateway = new PayPalGateway();
            _stripeGateway = new StripeGateway();
            _squareGateway = new SquareGateway();
            _transactionHistory = new List<PaymentResult>();
        }

        public PaymentResult ProcessTransaction(double amount, string currency, string gateway, CustomerInfo customer)
        {
            PaymentResult result = gateway.ToLower() switch
            {
                "paypal" => _paypalGateway.ProcessPayment(amount, currency, customer),
                "stripe" => _stripeGateway.ChargeCard(amount, currency, customer),
                "square" => _squareGateway.CreatePayment(amount, currency, customer),
                _ => new PaymentResult(false, null, "Unsupported payment gateway")
            };

            _transactionHistory.Add(result);
            GenerateTransactionReport(result, gateway, customer);

            return result;
        }

        public bool ProcessRefund(string transactionId, double amount, string gateway)
        {
            return gateway.ToLower() switch
            {
                "paypal" => _paypalGateway.ProcessRefund(transactionId, amount),
                "stripe" => _stripeGateway.ProcessRefund(transactionId, amount),
                "square" => _squareGateway.ProcessRefund(transactionId, amount),
                _ => false
            };
        }

        private void GenerateTransactionReport(PaymentResult result, string gateway, CustomerInfo customer)
        {
            var timestamp = DateTime.Now.ToString("yyyy-MM-ddTHH:mm:ss");
            var status = result.Success ? "SUCCESS" : "FAILED";
            Console.WriteLine($"Transaction Report [{timestamp}]: Gateway={gateway}, Customer={customer.Name}, Status={status}");
        }

        public List<PaymentResult> GetTransactionHistory()
        {
            return new List<PaymentResult>(_transactionHistory);
        }
    }

