import java.io.*;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.*;
import java.util.concurrent.*;
import java.util.stream.Collectors;
import java.util.zip.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class FileProcessor {
    private final String outputDirectory;
    private final String tempDirectory;
    private final ExecutorService executorService;
    private final Map<String, String> processingHistory;

    public FileProcessor(String outputDirectory, String tempDirectory) {
        this.outputDirectory = outputDirectory;
        this.tempDirectory = tempDirectory;
        this.executorService = Executors.newFixedThreadPool(4);
        this.processingHistory = new ConcurrentHashMap<>();
    }

    public CompletableFuture<List<ProcessingResult>> processFilesAsync(List<String> fileNames, ProcessingOptions options) {
        List<CompletableFuture<ProcessingResult>> futures = fileNames.stream()
            .map(fileName -> CompletableFuture.supplyAsync(() -> processIndividualFile(fileName, options), executorService))
            .collect(Collectors.toList());

        return CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]))
            .thenApply(v -> futures.stream().map(CompletableFuture::join).collect(Collectors.toList()));
    }

    private ProcessingResult processIndividualFile(String fileName, ProcessingOptions options) {
        try {
            String content = Files.readString(Paths.get(fileName));
            String checksum = calculateChecksum(content);

            if (processingHistory.containsKey(checksum)) {
                return new ProcessingResult(fileName, "Skipped - Already processed", false);
            }

            String processed = applyTransformations(content, options);

            if (options.compress) {
                processed = compressContent(processed);
            }

            String outputFileName = generateOutputFileName(fileName, options);
            Files.writeString(Paths.get(outputFileName), processed);

            if (options.createBackup) {
                createVersionedBackup(fileName);
            }

            if (options.validateOutput) {
                validateOutputFile(outputFileName);
            }

            processingHistory.put(checksum, outputFileName);
            updateProcessingLog(fileName, outputFileName);

            return new ProcessingResult(fileName, "Successfully processed", true);
        } catch (IOException | NoSuchAlgorithmException e) {
            return new ProcessingResult(fileName, "Error: " + e.getMessage(), false);
        }
    }

    private String applyTransformations(String content, ProcessingOptions options) {
        String result = content;

        if (options.toUpperCase) {
            result = result.toUpperCase();
        }

        if (options.removeEmptyLines) {
            result = Arrays.stream(result.split("\n"))
                .filter(line -> !line.trim().isEmpty())
                .collect(Collectors.joining("\n"));
        }

        if (options.addTimestamp) {
            result = "Processed at: " + new Date() + "\n" + result;
        }

        return result;
    }

    private String compressContent(String content) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (GZIPOutputStream gzipOut = new GZIPOutputStream(baos)) {
            gzipOut.write(content.getBytes());
        }
        return Base64.getEncoder().encodeToString(baos.toByteArray());
    }

    private String calculateChecksum(String content) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        byte[] hash = md.digest(content.getBytes());
        return Base64.getEncoder().encodeToString(hash);
    }

    private void createVersionedBackup(String fileName) throws IOException {
        String backupDir = tempDirectory + "/backups";
        Files.createDirectories(Paths.get(backupDir));

        String timestamp = String.valueOf(System.currentTimeMillis());
        String backupFileName = backupDir + "/" + Paths.get(fileName).getFileName() + "." + timestamp + ".backup";

        Files.copy(Paths.get(fileName), Paths.get(backupFileName));
    }

    private void validateOutputFile(String outputFileName) throws IOException {
        if (!Files.exists(Paths.get(outputFileName))) {
            throw new IOException("Output file was not created successfully");
        }

        if (Files.size(Paths.get(outputFileName)) == 0) {
            throw new IOException("Output file is empty");
        }
    }

    private String generateOutputFileName(String inputFileName, ProcessingOptions options) {
        String baseName = Paths.get(inputFileName).getFileName().toString();
        String extension = options.compress ? ".gz" : ".txt";
        return outputDirectory + "/processed_" + System.currentTimeMillis() + "_" + baseName + extension;
    }

    private void updateProcessingLog(String inputFile, String outputFile) throws IOException {
        String logEntry = String.format("%s: %s -> %s%n", new Date(), inputFile, outputFile);
        Files.writeString(Paths.get(tempDirectory + "/processing.log"), logEntry, StandardOpenOption.CREATE, StandardOpenOption.APPEND);
    }

    public void cleanup() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }

    public static class ProcessingOptions {
        public boolean toUpperCase = true;
        public boolean removeEmptyLines = false;
        public boolean addTimestamp = false;
        public boolean compress = false;
        public boolean createBackup = true;
        public boolean validateOutput = true;
    }

    public static class ProcessingResult {
        public final String fileName;
        public final String message;
        public final boolean success;

        public ProcessingResult(String fileName, String message, boolean success) {
            this.fileName = fileName;
            this.message = message;
            this.success = success;
        }
    }
}

import os
import shutil
import gzip
import base64
import hashlib
import asyncio
import aiofiles
from datetime import datetime
from typing import List, Dict, Optional, NamedTuple
from concurrent.futures import ThreadPoolExecutor
from dataclasses import dataclass
import json

@dataclass
class ProcessingOptions:
    to_upper_case: bool = True
    remove_empty_lines: bool = False
    add_timestamp: bool = False
    compress: bool = False
    create_backup: bool = True
    validate_output: bool = True

class ProcessingResult(NamedTuple):
    file_name: str
    message: str
    success: bool

class FileProcessor:
    def __init__(self, output_directory: str, temp_directory: str):
        self.output_directory = output_directory
        self.temp_directory = temp_directory
        self.executor = ThreadPoolExecutor(max_workers=4)
        self.processing_history: Dict[str, str] = {}
        self._ensure_directories_exist()

    def _ensure_directories_exist(self):
        os.makedirs(self.output_directory, exist_ok=True)
        os.makedirs(self.temp_directory, exist_ok=True)
        os.makedirs(f"{self.temp_directory}/backups", exist_ok=True)

    async def process_files_async(self, file_names: List[str], options: ProcessingOptions) -> List[ProcessingResult]:
        tasks = [self._process_individual_file(file_name, options) for file_name in file_names]
        return await asyncio.gather(*tasks)

    async def _process_individual_file(self, file_name: str, options: ProcessingOptions) -> ProcessingResult:
        try:
            async with aiofiles.open(file_name, 'r') as file:
                content = await file.read()

            checksum = self._calculate_checksum(content)

            if checksum in self.processing_history:
                return ProcessingResult(file_name, "Skipped - Already processed", False)

            processed = self._apply_transformations(content, options)

            if options.compress:
                processed = self._compress_content(processed)

            output_file_name = self._generate_output_filename(file_name, options)

            async with aiofiles.open(output_file_name, 'w') as output_file:
                await output_file.write(processed)

            if options.create_backup:
                await self._create_versioned_backup(file_name)

            if options.validate_output:
                self._validate_output_file(output_file_name)

            self.processing_history[checksum] = output_file_name
            await self._update_processing_log(file_name, output_file_name)

            return ProcessingResult(file_name, "Successfully processed", True)

        except Exception as e:
            return ProcessingResult(file_name, f"Error: {str(e)}", False)

    def _apply_transformations(self, content: str, options: ProcessingOptions) -> str:
        result = content

        if options.to_upper_case:
            result = result.upper()

        if options.remove_empty_lines:
            result = '\n'.join(line for line in result.split('\n') if line.strip())

        if options.add_timestamp:
            result = f"Processed at: {datetime.now()}\n{result}"

        return result

    def _compress_content(self, content: str) -> str:
        compressed = gzip.compress(content.encode('utf-8'))
        return base64.b64encode(compressed).decode('utf-8')

    def _calculate_checksum(self, content: str) -> str:
        return hashlib.sha256(content.encode('utf-8')).hexdigest()

    async def _create_versioned_backup(self, file_name: str):
        timestamp = str(int(datetime.now().timestamp() * 1000))
        backup_filename = f"{self.temp_directory}/backups/{os.path.basename(file_name)}.{timestamp}.backup"

        await asyncio.get_event_loop().run_in_executor(
            self.executor, shutil.copy2, file_name, backup_filename
        )

    def _validate_output_file(self, output_file_name: str):
        if not os.path.exists(output_file_name):
            raise IOError("Output file was not created successfully")

        if os.path.getsize(output_file_name) == 0:
            raise IOError("Output file is empty")

    def _generate_output_filename(self, input_file_name: str, options: ProcessingOptions) -> str:
        base_name = os.path.basename(input_file_name)
        extension = ".gz" if options.compress else ".txt"
        timestamp = int(datetime.now().timestamp() * 1000)
        return f"{self.output_directory}/processed_{timestamp}_{base_name}{extension}"

    async def _update_processing_log(self, input_file: str, output_file: str):
        log_entry = f"{datetime.now()}: {input_file} -> {output_file}\n"
        log_file = f"{self.temp_directory}/processing.log"

        async with aiofiles.open(log_file, 'a') as log:
            await log.write(log_entry)

    def cleanup(self):
        self.executor.shutdown(wait=True)

    def get_processing_statistics(self) -> Dict[str, any]:
        try:
            total_files = len(os.listdir(self.output_directory))
            total_size = sum(os.path.getsize(os.path.join(self.output_directory, f)) 
                           for f in os.listdir(self.output_directory) 
                           if os.path.isfile(os.path.join(self.output_directory, f)))

            return {
                "total_processed_files": total_files,
                "total_output_size": total_size,
                "processing_history_count": len(self.processing_history)
            }
        except OSError:
            return {"error": "Unable to calculate statistics"}

    def export_processing_history(self, export_file: str) -> bool:
        try:
            with open(export_file, 'w') as f:
                json.dump(self.processing_history, f, indent=2)
            return True
        except IOError:
            return False

import kotlinx.coroutines.*
import kotlinx.coroutines.channels.Channel
import java.io.File
import java.nio.file.Files
import java.nio.file.Paths
import java.nio.file.StandardCopyOption
import java.security.MessageDigest
import java.util.*
import java.util.concurrent.ConcurrentHashMap
import java.util.zip.GZIPOutputStream
import java.io.ByteArrayOutputStream
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import kotlinx.serialization.encodeToString

@Serializable
data class ProcessingOptions(
    val toUpperCase: Boolean = true,
    val removeEmptyLines: Boolean = false,
    val addTimestamp: Boolean = false,
    val compress: Boolean = false,
    val createBackup: Boolean = true,
    val validateOutput: Boolean = true
)

data class ProcessingResult(
    val fileName: String,
    val message: String,
    val success: Boolean
)

class FileProcessor(private val outputDirectory: String, private val tempDirectory: String) {
    private val processingHistory = ConcurrentHashMap<String, String>()
    private val processingScope = CoroutineScope(Dispatchers.IO + SupervisorJob())

    init {
        ensureDirectoriesExist()
    }

    private fun ensureDirectoriesExist() {
        File(outputDirectory).mkdirs()
        File(tempDirectory).mkdirs()
        File("$tempDirectory/backups").mkdirs()
    }

    suspend fun processFilesAsync(fileNames: List<String>, options: ProcessingOptions): List<ProcessingResult> {
        return withContext(Dispatchers.IO) {
            fileNames.map { fileName ->
                async { processIndividualFile(fileName, options) }
            }.awaitAll()
        }
    }

    private suspend fun processIndividualFile(fileName: String, options: ProcessingOptions): ProcessingResult {
        return try {
            val content = withContext(Dispatchers.IO) { File(fileName).readText() }
            val checksum = calculateChecksum(content)

            if (processingHistory.containsKey(checksum)) {
                return ProcessingResult(fileName, "Skipped - Already processed", false)
            }

            var processed = applyTransformations(content, options)

            if (options.compress) {
                processed = compressContent(processed)
            }

            val outputFileName = generateOutputFileName(fileName, options)

            withContext(Dispatchers.IO) {
                File(outputFileName).writeText(processed)
            }

            if (options.createBackup) {
                createVersionedBackup(fileName)
            }

            if (options.validateOutput) {
                validateOutputFile(outputFileName)
            }

            processingHistory[checksum] = outputFileName
            updateProcessingLog(fileName, outputFileName)

            ProcessingResult(fileName, "Successfully processed", true)
        } catch (e: Exception) {
            ProcessingResult(fileName, "Error: ${e.message}", false)
        }
    }

    private fun applyTransformations(content: String, options: ProcessingOptions): String {
        var result = content

        if (options.toUpperCase) {
            result = result.uppercase()
        }

        if (options.removeEmptyLines) {
            result = result.lines().filter { it.trim().isNotEmpty() }.joinToString("\n")
        }

        if (options.addTimestamp) {
            result = "Processed at: ${Date()}\n$result"
        }

        return result
    }

    private fun compressContent(content: String): String {
        val outputStream = ByteArrayOutputStream()
        GZIPOutputStream(outputStream).use { gzip ->
            gzip.write(content.toByteArray())
        }
        return Base64.getEncoder().encodeToString(outputStream.toByteArray())
    }

    private fun calculateChecksum(content: String): String {
        val digest = MessageDigest.getInstance("SHA-256")
        return digest.digest(content.toByteArray()).joinToString("") { "%02x".format(it) }
    }

    private suspend fun createVersionedBackup(fileName: String) {
        val timestamp = System.currentTimeMillis()
        val backupFileName = "$tempDirectory/backups/${File(fileName).name}.$timestamp.backup"

        withContext(Dispatchers.IO) {
            Files.copy(Paths.get(fileName), Paths.get(backupFileName), StandardCopyOption.REPLACE_EXISTING)
        }
    }

    private fun validateOutputFile(outputFileName: String) {
        val file = File(outputFileName)
        if (!file.exists()) {
            throw java.io.IOException("Output file was not created successfully")
        }

        if (file.length() == 0L) {
            throw java.io.IOException("Output file is empty")
        }
    }

    private fun generateOutputFileName(inputFileName: String, options: ProcessingOptions): String {
        val baseName = File(inputFileName).name
        val extension = if (options.compress) ".gz" else ".txt"
        val timestamp = System.currentTimeMillis()
        return "$outputDirectory/processed_${timestamp}_$baseName$extension"
    }

    private suspend fun updateProcessingLog(inputFile: String, outputFile: String) {
        val logEntry = "${Date()}: $inputFile -> $outputFile\n"
        val logFile = "$tempDirectory/processing.log"

        withContext(Dispatchers.IO) {
            File(logFile).appendText(logEntry)
        }
    }

    fun cleanup() {
        processingScope.cancel()
    }

    fun getProcessingStatistics(): Map<String, Any> {
        return try {
            val outputDir = File(outputDirectory)
            val files = outputDir.listFiles()?.filter { it.isFile } ?: emptyList()
            val totalFiles = files.size
            val totalSize = files.sumOf { it.length() }

            mapOf(
                "total_processed_files" to totalFiles,
                "total_output_size" to totalSize,
                "processing_history_count" to processingHistory.size
            )
        } catch (e: Exception) {
            mapOf("error" to "Unable to calculate statistics")
        }
    }

    fun exportProcessingHistory(exportFile: String): Boolean {
        return try {
            val json = Json.encodeToString(processingHistory)
            File(exportFile).writeText(json)
            true
        } catch (e: Exception) {
            false
        }
    }

    suspend fun batchProcessWithRetry(fileNames: List<String>, options: ProcessingOptions, maxRetries: Int = 3): List<ProcessingResult> {
        val results = mutableListOf<ProcessingResult>()

        for (fileName in fileNames) {
            var attempts = 0
            var lastResult: ProcessingResult

            do {
                attempts++
                lastResult = processIndividualFile(fileName, options)

                if (lastResult.success) {
                    results.add(lastResult)
                    break
                }

                if (attempts < maxRetries) {
                    delay(1000 * attempts)
                }
            } while (attempts < maxRetries)

            if (!lastResult.success) {
                results.add(lastResult)
            }
        }

        return results
    }

    fun getDetailedProcessingReport(): String {
        val outputDir = File(outputDirectory)
        val backupDir = File("$tempDirectory/backups")

        val outputFiles = outputDir.listFiles()?.filter { it.isFile } ?: emptyList()
        val backupFiles = backupDir.listFiles()?.filter { it.isFile } ?: emptyList()

        return buildString {
            appendLine("=== File Processing Report ===")
            appendLine("Generated: ${Date()}")
            appendLine("Output Directory: $outputDirectory")
            appendLine("Temp Directory: $tempDirectory")
            appendLine("")
            appendLine("Processing Statistics:")
            appendLine("- Total processed files: ${outputFiles.size}")
            appendLine("- Total backup files: ${backupFiles.size}")
            appendLine("- Processing history entries: ${processingHistory.size}")
            appendLine("- Total output size: ${outputFiles.sumOf { it.length() }} bytes")
            appendLine("")
            appendLine("Recent Files:")
            outputFiles.sortedByDescending { it.lastModified() }.take(10).forEach { file ->
                appendLine("- ${file.name} (${file.length()} bytes, ${Date(file.lastModified())})")
            }
        }
    }
}

