public class ProcessingOptions
{
    public bool ToUpperCase { get; set; } = true;
    public bool RemoveEmptyLines { get; set; } = false;
    public bool AddTimestamp { get; set; } = false;
    public bool Compress { get; set; } = false;
    public bool CreateBackup { get; set; } = true;
    public bool ValidateOutput { get; set; } = true;
}

public class ProcessingResult
{
    public string FileName { get; set; }
    public string Message { get; set; }
    public bool Success { get; set; }

    public ProcessingResult(string fileName, string message, bool success)
    {
        FileName = fileName;
        Message = message;
        Success = success;
    }
}

public class FileProcessor
{
    private readonly string outputDirectory;
    private readonly string tempDirectory;
    private readonly ConcurrentDictionary<string, string> processingHistory;
    private readonly SemaphoreSlim semaphore;

    public FileProcessor(string outputDirectory, string tempDirectory)
    {
        this.outputDirectory = outputDirectory;
        this.tempDirectory = tempDirectory;
        this.processingHistory = new ConcurrentDictionary<string, string>();
        this.semaphore = new SemaphoreSlim(Environment.ProcessorCount, Environment.ProcessorCount);
        EnsureDirectoriesExist();
    }

    private void EnsureDirectoriesExist()
    {
        Directory.CreateDirectory(outputDirectory);
        Directory.CreateDirectory(tempDirectory);
        Directory.CreateDirectory(Path.Combine(tempDirectory, "backups"));
    }

    public async Task<List<ProcessingResult>> ProcessFilesAsync(List<string> fileNames, ProcessingOptions options)
    {
        var tasks = fileNames.Select(fileName => ProcessIndividualFileAsync(fileName, options));
        var results = await Task.WhenAll(tasks);
        return results.ToList();
    }

    private async Task<ProcessingResult> ProcessIndividualFileAsync(string fileName, ProcessingOptions options)
    {
        await semaphore.WaitAsync();
        try
        {
            var content = await File.ReadAllTextAsync(fileName);
            var checksum = CalculateChecksum(content);

            if (processingHistory.ContainsKey(checksum))
            {
                return new ProcessingResult(fileName, "Skipped - Already processed", false);
            }

            var processed = ApplyTransformations(content, options);

            if (options.Compress)
            {
                processed = CompressContent(processed);
            }

            var outputFileName = GenerateOutputFileName(fileName, options);

            await File.WriteAllTextAsync(outputFileName, processed);

            if (options.CreateBackup)
            {
                await CreateVersionedBackupAsync(fileName);
            }

            if (options.ValidateOutput)
            {
                ValidateOutputFile(outputFileName);
            }

            processingHistory[checksum] = outputFileName;
            await UpdateProcessingLogAsync(fileName, outputFileName);

            return new ProcessingResult(fileName, "Successfully processed", true);
        }
        catch (Exception ex)
        {
            return new ProcessingResult(fileName, $"Error: {ex.Message}", false);
        }
        finally
        {
            semaphore.Release();
        }
    }

    private string ApplyTransformations(string content, ProcessingOptions options)
    {
        var result = content;

        if (options.ToUpperCase)
        {
            result = result.ToUpper();
        }

        if (options.RemoveEmptyLines)
        {
            result = string.Join("\n", result.Split('\n').Where(line => !string.IsNullOrWhiteSpace(line)));
        }

        if (options.AddTimestamp)
        {
            result = $"Processed at: {DateTime.Now}\n{result}";
        }

        return result;
    }

    private string CompressContent(string content)
    {
        var bytes = Encoding.UTF8.GetBytes(content);

        using (var output = new MemoryStream())
        using (var gzip = new GZipStream(output, CompressionMode.Compress))
        {
            gzip.Write(bytes, 0, bytes.Length);
            gzip.Close();
            return Convert.ToBase64String(output.ToArray());
        }
    }

    private string CalculateChecksum(string content)
    {
        using (var sha256 = SHA256.Create())
        {
            var bytes = Encoding.UTF8.GetBytes(content);
            var hash = sha256.ComputeHash(bytes);
            return BitConverter.ToString(hash).Replace("-", "").ToLower();
        }
    }

    private async Task CreateVersionedBackupAsync(string fileName)
    {
        var timestamp = DateTimeOffset.Now.ToUnixTimeMilliseconds();
        var backupFileName = Path.Combine(tempDirectory, "backups", $"{Path.GetFileName(fileName)}.{timestamp}.backup");

        await Task.Run(() => File.Copy(fileName, backupFileName, true));
    }

    private void ValidateOutputFile(string outputFileName)
    {
        if (!File.Exists(outputFileName))
        {
            throw new IOException("Output file was not created successfully");
        }

        var fileInfo = new FileInfo(outputFileName);
        if (fileInfo.Length == 0)
        {
            throw new IOException("Output file is empty");
        }
    }

    private string GenerateOutputFileName(string inputFileName, ProcessingOptions options)
    {
        var baseName = Path.GetFileName(inputFileName);
        var extension = options.Compress ? ".gz" : ".txt";
        var timestamp = DateTimeOffset.Now.ToUnixTimeMilliseconds();
        return Path.Combine(outputDirectory, $"processed_{timestamp}_{baseName}{extension}");
    }

    private async Task UpdateProcessingLogAsync(string inputFile, string outputFile)
    {
        var logEntry = $"{DateTime.Now}: {inputFile} -> {outputFile}\n";
        var logFile = Path.Combine(tempDirectory, "processing.log");

        await File.AppendAllTextAsync(logFile, logEntry);
    }

    public Dictionary<string, object> GetProcessingStatistics()
    {
        try
        {
            var outputDir = new DirectoryInfo(outputDirectory);
            var files = outputDir.GetFiles().Where(f => f.Exists).ToList();
            var totalFiles = files.Count;
            var totalSize = files.Sum(f => f.Length);

            return new Dictionary<string, object>
            {
                ["total_processed_files"] = totalFiles,
                ["total_output_size"] = totalSize,
                ["processing_history_count"] = processingHistory.Count
            };
        }
        catch (Exception)
        {
            return new Dictionary<string, object> { ["error"] = "Unable to calculate statistics" };
        }
    }

    public bool ExportProcessingHistory(string exportFile)
    {
        try
        {
            var json = JsonSerializer.Serialize(processingHistory, new JsonSerializerOptions { WriteIndented = true });
            File.WriteAllText(exportFile, json);
            return true;
        }
        catch (Exception)
        {
            return false;
        }
    }

    public async Task<List<ProcessingResult>> BatchProcessWithRetryAsync(List<string> fileNames, ProcessingOptions options, int maxRetries = 3)
    {
        var results = new List<ProcessingResult>();

        foreach (var fileName in fileNames)
        {
            var attempts = 0;
            ProcessingResult lastResult;

            do
            {
                attempts++;
                lastResult = await ProcessIndividualFileAsync(fileName, options);

                if (lastResult.Success)
                {
                    results.Add(lastResult);
                    break;
                }

                if (attempts < maxRetries)
                {
                    await Task.Delay(1000 * attempts);
                }
            } while (attempts < maxRetries);

            if (!lastResult.Success)
            {
                results.Add(lastResult);
            }
        }

        return results;
    }

    public string GetDetailedProcessingReport()
    {
        var outputDir = new DirectoryInfo(outputDirectory);
        var backupDir = new DirectoryInfo(Path.Combine(tempDirectory, "backups"));

        var outputFiles = outputDir.Exists ? outputDir.GetFiles().Where(f => f.Exists).ToList() : new List<FileInfo>();
        var backupFiles = backupDir.Exists ? backupDir.GetFiles().Where(f => f.Exists).ToList() : new List<FileInfo>();

        var report = new StringBuilder();
        report.AppendLine("=== File Processing Report ===");
        report.AppendLine($"Generated: {DateTime.Now}");
        report.AppendLine($"Output Directory: {outputDirectory}");
        report.AppendLine($"Temp Directory: {tempDirectory}");
        report.AppendLine();
        report.AppendLine("Processing Statistics:");
        report.AppendLine($"- Total processed files: {outputFiles.Count}");
        report.AppendLine($"- Total backup files: {backupFiles.Count}");
        report.AppendLine($"- Processing history entries: {processingHistory.Count}");
        report.AppendLine($"- Total output size: {outputFiles.Sum(f => f.Length)} bytes");
        report.AppendLine();
        report.AppendLine("Recent Files:");

        var recentFiles = outputFiles.OrderByDescending(f => f.LastWriteTime).Take(10);
        foreach (var file in recentFiles)
        {
            report.AppendLine($"- {file.Name} ({file.Length} bytes, {file.LastWriteTime})");
        }

        return report.ToString();
    }

    public void Dispose()
    {
        semaphore?.Dispose();
    }
}

