using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using System.Text.RegularExpressions;

public class TwilioSMS
{
    private string apiKey;
    private string accountSid;
    private string authToken;
    private Dictionary<string, string> configuration;

    public TwilioSMS(string apiKey, string accountSid, string authToken)
    {
        this.apiKey = apiKey;
        this.accountSid = accountSid;
        this.authToken = authToken;
        this.configuration = new Dictionary<string, string>();
        InitializeConfiguration();
    }

    private void InitializeConfiguration()
    {
        configuration["timeout"] = "30000";
        configuration["retries"] = "3";
        configuration["baseUrl"] = "https://api.twilio.com/2010-04-01";
    }

    public void SendSMS(string phoneNumber, string message)
    {
        AuthenticateWithTwilio();
        ValidatePhoneNumber(phoneNumber);
        Console.WriteLine($"Sending SMS via Twilio to {phoneNumber}: {message}");
    }

    public async Task SendBulkSMS(string[] phoneNumbers, string message)
    {
        var tasks = new List<Task>();
        foreach (var number in phoneNumbers)
        {
            tasks.Add(Task.Run(() => SendSMS(number, message)));
        }
        await Task.WhenAll(tasks);
    }

    public void SendScheduledSMS(string phoneNumber, string message, int delaySeconds)
    {
        var timer = new Timer(callback =>
        {
            SendSMS(phoneNumber, message);
        }, null, delaySeconds * 1000, Timeout.Infinite);
    }

    private void AuthenticateWithTwilio()
    {
        Console.WriteLine($"Authenticating with Twilio API using SID: {accountSid}");
        Console.WriteLine($"Using auth token: {authToken.Substring(0, 5)}...");
    }

    private void ValidatePhoneNumber(string phoneNumber)
    {
        var phoneRegex = new Regex(@"^\+?[1-9]\d{1,14}$");
        if (!phoneRegex.IsMatch(phoneNumber))
        {
            throw new ArgumentException("Invalid phone number format");
        }
    }

    public void UpdateConfiguration(string key, string value)
    {
        configuration[key] = value;
    }
}

